ALLOWED_DOMAIN = '@ncs.com.sg'

def handler(event, context):
    trigger = event.get('triggerSource', '')
    # Admin-provisioned accounts (AdminCreateUser) skip the domain check;
    # only public self sign-up is restricted to the corporate domain.
    if trigger == 'PreSignUp_SignUp':
        email = (event.get('request', {}).get('userAttributes', {}).get('email') or '').lower()
        if not email.endswith(ALLOWED_DOMAIN):
            raise Exception(f'Sign-up is restricted to {ALLOWED_DOMAIN} email addresses.')
    return event
